    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if(!(cin >> n)) return 0;
    string s;
    cin >> s;

    int ans = 0;
    int cnt = 0;
    for(char c : s) {
        if(c == 'x') {
            ++cnt;
            if(cnt >= 3) ++ans;
        } else {
            cnt = 0;
        }
    }
    cout << ans << "\n";
    return 0;
}
